INSERT INTO indicators (id, code, name, category_id, bidang_id, wewenang_bidang, pejabat_penanggung_jawab, seksi_pelaksana, unit, polarization, definition, formula, source, sort_order) VALUES
('IND-IKU-KAB-01', 'IKU-KAB-01', 'Indeks Layanan Infrastruktur Daerah', 'iku_daerah', 'bidang_sekretariat', 'Sekretariat DINPUTARU', 'Amirul Mukminin, S.T., M.Si. (Sekretaris Dinas)', 'Subbag Program, Keuangan & Akuntabilitas Kinerja', 'Angka', 'maximize', 'Indikator komposit makro yang mengukur tingkat ketersediaan, kualitas, keandalan, dan keterjangkauan pelayanan infrastruktur dasar ke-PU-an di Kabupaten Demak yang mencakup kemantapan jalan, kinerja irigasi, akses air minum aman, dan sanitasi layak.', '(Indeks Jalan Mantap + Indeks Irigasi + Indeks Air Minum + Indeks Sanitasi) / 4', 'Dokumen RPJMD Kabupaten Demak & Renstra DINPUTARU Kabupaten Demak', 1),
('IND-IKD-01', 'IKD-01', 'Akses Rumah Tangga Perkotaan terhadap Air Siap Minum Perpipaan', 'ikd', 'bidang_ck', 'Bidang Cipta Karya & Perumahan', 'Dian Pratama, S.T., M.Sc. (Kabid Cipta Karya)', 'Seksi Air Minum, Sanitasi & Tata Bangunan', '%', 'maximize', 'Persentase rumah tangga di kawasan perkotaan Kabupaten Demak yang telah terlayani sambungan langsung air siap minum melalui jaringan perpipaan berstandar mutu air minum nasional.', '(Jumlah RT Perkotaan Terlayani Air Siap Minum Perpipaan / Total Rumah Tangga Kawasan Perkotaan) x 100%', 'PDAM Tirta Kalijaga Demak & Buku Laporan SPAM DINPUTARU', 2),
('IND-IKD-02', 'IKD-02', 'Indeks Kinerja Sistem Irigasi Kewenangan Kabupaten', 'ikd', 'bidang_sda', 'Bidang Sumber Daya Air & Bina Konstruksi', 'Ir. Hendra Wijaya, M.Eng. (Kabid SDA & BK)', 'Seksi Irigasi, Pengendalian Banjir & Pembinaan Jasa Konstruksi', 'Angka', 'maximize', 'Indeks kinerja sistem irigasi kewenangan Kabupaten Demak berbasis aplikasi E-PAKSI yang mengevaluasi prasarana fisik, produktivitas tanam, sarana penunjang, organisasi personalia, dokumentasi, dan kelembagaan P3A.', '∑ (Skor Komponen Evaluasi x Bobot Komponen) [Sesuai Permen PUPR No. 12/PRT/M/2015]', 'Aplikasi E-PAKSI Kementerian PUPR & Survei IKSI Bidang SDA DINPUTARU', 3),
('IND-IKD-03', 'IKD-03', 'Rumah Tangga dengan Akses Sanitasi Aman', 'ikd', 'bidang_ck', 'Bidang Cipta Karya & Perumahan', 'Dian Pratama, S.T., M.Sc. (Kabid Cipta Karya)', 'Seksi Air Minum, Sanitasi & Tata Bangunan', '%', 'maximize', 'Persentase rumah tangga di Kabupaten Demak yang memiliki akses fasilitas sanitasi milik sendiri dengan kloset leher angsa dan tangki septik aman yang disedot secara berkala (L2T2/IPLT).', '(Jumlah RT Akses Sanitasi Aman / Total Rumah Tangga Kabupaten Demak) x 100%', 'Survei EHRA, SSGI, BPS Kabupaten Demak & Data Seksi Sanitasi DINPUTARU', 4),
('IND-IKD-04', 'IKD-04', 'Persentase Rumah Tangga dengan Akses Air Minum Aman', 'ikd', 'bidang_ck', 'Bidang Cipta Karya & Perumahan', 'Dian Pratama, S.T., M.Sc. (Kabid Cipta Karya)', 'Seksi Air Minum, Sanitasi & Tata Bangunan', '%', 'maximize', 'Persentase rumah tangga dengan akses air minum layak, bebas kontaminasi bakteriologis, berada di premis, dan tersedia sepanjang waktu sesuai target SDGs 6.1.', '(Jumlah RT dengan Akses Air Minum Aman / Total Rumah Tangga Kabupaten Demak) x 100%', 'Data Susenas BPS Kabupaten Demak & Laporan Kinerja Bidang Cipta Karya', 5),
('IND-IKD-05', 'IKD-05', 'Indeks Layanan Infrastruktur daerah', 'ikd', 'bidang_sekretariat', 'Sekretariat DINPUTARU', 'Amirul Mukminin, S.T., M.Si. (Sekretaris Dinas)', 'Subbag Program, Keuangan & Akuntabilitas Kinerja', 'Angka', 'maximize', 'Indikator komposit indeks layanan infrastruktur ke-PU-an daerah Kabupaten Demak.', '(Indeks Jalan + Indeks Irigasi + Indeks Air Minum + Indeks Sanitasi) / 4', 'LAKIP DINPUTARU Kabupaten Demak & Laporan Kinerja Pembangunan Daerah', 6),
('IND-IKD-06', 'IKD-06', 'Indeks Kinerja Infrastruktur Daerah', 'ikd', 'bidang_sekretariat', 'Sekretariat DINPUTARU', 'Amirul Mukminin, S.T., M.Si. (Sekretaris Dinas)', 'Subbag Program, Keuangan & Akuntabilitas Kinerja', 'Angka', 'maximize', 'Tingkat pemenuhan dan keberfungsian sarana dan prasarana infrastruktur daerah kewenangan DINPUTARU.', '(Total Aset Infrastruktur Berfungsi Baik / Total Inventarisasi Aset Infrastruktur) x 100%', 'Buku Laporan Neraca Aset DINPUTARU Kab. Demak', 7),
('IND-IKD-07', 'IKD-07', 'Persentase Panjang Jalan Kondisi Permukaan Mantap Kewenangan Kabupaten/Kota', 'ikd', 'bidang_bm', 'Bidang Bina Marga', 'Budi Santoso, S.T., M.T. (Kabid Bina Marga)', 'Seksi Pembangunan & Preservasi Jalan Jembatan', '%', 'maximize', 'Persentase panjang jalan kabupaten dalam kondisi permukaan baik dan sedang sesuai standar Permen PUPR No. 14/PRT/M/2018 terhadap total panjang jalan kabupaten.', '((Panjang Jalan Kondisi Baik + Panjang Jalan Kondisi Sedang) / Total Panjang Jalan Kabupaten) x 100%', 'Hasil Survei Kondisi Jalan (SKJ / RNI) Bidang Bina Marga DINPUTARU', 8),
('IND-IKU-PD-01', 'IKU-PD-01', 'Nilai SAKIP Perangkat Daerah', 'iku_pd', 'bidang_sekretariat', 'Sekretariat DINPUTARU', 'Amirul Mukminin, S.T., M.Si. (Sekretaris Dinas)', 'Subbag Program, Keuangan & Akuntabilitas Kinerja', 'Angka', 'maximize', 'Nilai evaluasi akuntabilitas kinerja perangkat daerah oleh Inspektorat Daerah Kabupaten Demak meliputi perencanaan, pengukuran, pelaporan, dan evaluasi internal (PermenPAN-RB No. 88/2021).', 'Total Skor Evaluasi AKIP (Skala 0 - 100)', 'Laporan Hasil Evaluasi (LHE) AKIP Inspektorat Daerah Kabupaten Demak', 9),
('IND-IKU-PD-02', 'IKU-PD-02', 'Indeks Pelayanan Publik Perangkat Daerah', 'iku_pd', 'bidang_sekretariat', 'Sekretariat DINPUTARU', 'Amirul Mukminin, S.T., M.Si. (Sekretaris Dinas)', 'Subbag Program, Keuangan & Akuntabilitas Kinerja', 'Angka', 'maximize', 'Indeks kepatuhan dan mutu standar pelayanan perizinan teknis, PBG, dan rekomendasi tata ruang pada DINPUTARU Kabupaten Demak (PermenPAN-RB No. 17/2017).', 'Rata-rata Skor 6 Aspek Pelayanan Publik KemenPAN-RB (Skala 1 - 5)', 'Evaluasi Kinerja Pelayanan Publik KemenPAN-RB & Bagian Organisasi', 10),
('IND-IKU-PD-03', 'IKU-PD-03', 'Persentase Panjang Jalan Kondisi Permukaan Mantap Kewenangan Kabupaten/Kota', 'iku_pd', 'bidang_bm', 'Bidang Bina Marga', 'Budi Santoso, S.T., M.T. (Kabid Bina Marga)', 'Seksi Pembangunan & Preservasi Jalan Jembatan', '%', 'maximize', 'Tingkat kemantapan infrastruktur jaringan jalan kabupaten dalam melayani konektivitas antar wilayah dan pusat produksi di Kabupaten Demak.', '((Panjang Jalan Baik + Sedang) / Total Panjang Jalan Kabupaten) x 100%', 'Data Survei Kondisi Jalan Bidang Bina Marga DINPUTARU', 11),
('IND-IKU-PD-04', 'IKU-PD-04', 'Persentase capaian kinerja pengelolaan sumber daya air', 'iku_pd', 'bidang_sekretariat', 'Sekretariat DINPUTARU', 'Amirul Mukminin, S.T., M.Si. (Sekretaris Dinas)', 'Subbag Program, Keuangan & Akuntabilitas Kinerja', '%', 'maximize', 'Persentase ketercapaian target pengelolaan jaringan irigasi, drainase utama, dan pemeliharaan sarpras pengendali banjir/rob di Kabupaten Demak.', '(Rata-rata Capaian Sub-Kegiatan SDA / Target) x 100%', 'Laporan Kinerja Bidang SDA & Bina Konstruksi DINPUTARU', 12),
('IND-IKU-PD-05', 'IKU-PD-05', 'Persentase capaian kinerja penyelenggaraan penataan ruang', 'iku_pd', 'bidang_sekretariat', 'Sekretariat DINPUTARU', 'Amirul Mukminin, S.T., M.Si. (Sekretaris Dinas)', 'Subbag Program, Keuangan & Akuntabilitas Kinerja', '%', 'maximize', 'Persentase capaian kinerja penyelenggaraan penataan ruang meliputi penyusunan RDTR, penerbitan KKPR tepat waktu, dan pengawasan pemanfaatan ruang.', '(Jumlah Layanan Penataan Ruang Terpenuhi / Total Agenda Penataan Ruang) x 100%', 'Laporan Penyelenggaraan Tata Ruang Bidang Penataan Ruang & Pertanahan', 13),
('IND-IKK-01', 'IKK-01', 'Rasio luas kawasan permukiman rawan banjir yang terlindungi oleh infrastruktur pengendalian banjir di Wilayah Sungai Kewenangan Kab/Kota', 'ikk', 'bidang_sda', 'Bidang Sumber Daya Air & Bina Konstruksi', 'Ir. Hendra Wijaya, M.Eng. (Kabid SDA & BK)', 'Seksi Irigasi, Pengendalian Banjir & Pembinaan Jasa Konstruksi', '%', 'maximize', 'Indikator Kinerja Kunci (IKK) evaluasi penyelenggaraan urusan ke-PU-an dan penataan ruang pemerintah daerah Kabupaten Demak sesuai pedoman LPPD Kemendagri.', '(Realisasi Output Terpenuhi / Target Penetapan Kinerja) x 100%', 'Laporan Penyelenggaraan Pemerintahan Daerah (LPPD) Kabupaten Demak', 14),
('IND-IKK-02', 'IKK-02', 'Rasio luas kawasan permukiman sepanjang pantai rawan abrasi, erosi, dan akresi yang terlindungi oleh infrastruktur pengaman pantai di Wilayah Sungai Kewenangan Kab/Kota', 'ikk', 'bidang_sda', 'Bidang Sumber Daya Air & Bina Konstruksi', 'Ir. Hendra Wijaya, M.Eng. (Kabid SDA & BK)', 'Seksi Irigasi, Pengendalian Banjir & Pembinaan Jasa Konstruksi', '%', 'maximize', 'Indikator Kinerja Kunci (IKK) evaluasi penyelenggaraan urusan ke-PU-an dan penataan ruang pemerintah daerah Kabupaten Demak sesuai pedoman LPPD Kemendagri.', '(Realisasi Output Terpenuhi / Target Penetapan Kinerja) x 100%', 'Laporan Penyelenggaraan Pemerintahan Daerah (LPPD) Kabupaten Demak', 15),
