INSERT INTO bank_data (id, title, category, bidang_id, year, document_number, source, metric_value, metric_label, stat_summary, file_type, file_size, tags, description) VALUES
('BD-BM-01', 'Data Panjang Jalan Kabupaten Menurut Tingkat Kondisi Jalan di Kabupaten Demak', 'Statistik BPS 2025', 'bina_marga', 2024, 'BPS-3321/DDA-2025/BM-01', 'BPS Kab. Demak (Demak Dalam Angka 2025) & Survei SKJ DINPUTARU', '641,20 Km', 'Total Panjang Jalan Kabupaten', 'Kemantapan Jalan: 81,10% (Kondisi Baik: 441,85 Km | Sedang: 78,15 Km | Rusak Ringan: 63,20 Km | Rusak Berat: 58,00 Km)', 'XLSX & PDF', '2.4 MB', 'BPS 2025, Bina Marga, Kondisi Jalan, Jalan Mantap, SKJ', 'Data rincian kondisi kemantapan jalan kabupaten di 14 kecamatan se-Kabupaten Demak yang dipublikasikan dalam buku Kabupaten Demak Dalam Angka 2025 oleh BPS Kabupaten Demak.'),
('BD-BM-02', 'Data Panjang Jalan Kabupaten Menurut Jenis Permukaan di 14 Kecamatan Kab. Demak', 'Statistik BPS 2025', 'bina_marga', 2024, 'BPS-3321/DDA-2025/BM-02', 'BPS Kab. Demak (Demak Dalam Angka 2025)', '392,10 Km', 'Panjang Permukaan Aspal Hotmix', 'Aspal: 392,10 Km (61,15%) | Beton (Rigid): 218,40 Km (34,06%) | Kerikil: 23,50 Km | Tanah: 7,20 Km', 'XLSX', '1.8 MB', 'BPS 2025, Jenis Permukaan, Beton Rigid, Hotmix, Infrastruktur', 'Klasifikasi konstruksi permukaan perkerasan jalan kabupaten di Kabupaten Demak guna perencanaan preservasi dan peningkatan jalan berkala.'),
('BD-BM-03', 'Data Inventarisasi dan Kondisi Kelayakan Struktural Jembatan Kabupaten Demak', 'Laporan Teknis', 'bina_marga', 2024, 'DINPUTARU-BM/BMS-2024/03', 'Database Bridge Management System (BMS) DINPUTARU Demak', '284 Unit', 'Total Unit Jembatan Kabupaten', 'Kondisi Baik: 226 Unit | Kondisi Sedang: 41 Unit | Kritis/Perlu Penggantian: 17 Unit (Total Bentang: 3.420 meter)', 'PDF & SHP', '5.1 MB', 'Jembatan, BMS, Bina Marga, Kelayakan Struktur, Keselamatan', 'Buku induk inventaris jembatan kabupaten yang memuat koordinat lokasi, bentang jembatan, tipe gelagar (beton/baja), dan nilai kondisi keamanan struktural.'),
('BD-BM-04', 'Data Koridor Jalan Strategis Penghubung Kawasan Pesisir, Industri & Pusat Pertanian', 'Data Spasial / GIS', 'bina_marga', 2024, 'GIS-DINPUTARU/BM-KORIDOR/2024', 'Bidang Bina Marga DINPUTARU Demak', '18 Ruas', 'Ruas Koridor Utama Prioritas', 'Menghubungkan Sentra Padi Dempet-Godong, Kawasan Industri Sayung, Sentra Garam Wedung, dan Jalur Alternatif Semarang-Kudus', 'SHP & GeoJSON', '8.4 MB', 'Koridor Strategis, GIS, Jalan Industri, Pesisir, Demak', 'Peta spasial koridor jalan prioritas penunjang mobilitas logistik dan pengentasan kemiskinan ekstrem di wilayah pesisir dan pedesaan Kabupaten Demak.'),
('BD-SDA-01', 'Data Luas Daerah Irigasi (DI) Kewenangan Kabupaten Demak & Kondisi Keberfungsian', 'Statistik BPS 2025', 'sda', 2024, 'BPS-3321/DDA-2025/SDA-01', 'BPS Kab. Demak (Demak Dalam Angka 2025) & E-PAKSI DINPUTARU', '28.450 Ha', 'Luas Baku Sawah Teraliri DI Kabupaten', '112 Daerah Irigasi Kewenangan Kabupaten | 85,0% Jaringan Primer/Sekunder Berfungsi Optimal (24.180 Ha)', 'XLSX & PDF', '3.2 MB', 'BPS 2025, Irigasi, E-PAKSI, Pertanian, Sumber Daya Air', 'Data spasial dan tabular 112 Daerah Irigasi (DI) kewenangan Pemerintah Kabupaten Demak di bawah 1.000 Ha sesuai Kepmen PUPR.'),
('BD-SDA-02', 'Data Sarana Rumah Pompa dan Pompa Pengendali Rob Kawasan Pesisir Kabupaten Demak', 'Laporan Teknis', 'sda', 2024, 'DINPUTARU-SDA/POMPA-ROB/2024', 'Bidang Sumber Daya Air DINPUTARU Kabupaten Demak', '48 Unit', 'Pompa Air Pengendali Rob & Banjir', 'Kapasitas Pompa: 250 s.d. 1.500 liter/detik | Melindungi Polder Sriwulan, Morosari Sayung, Morodemak, Karangtengah, dan Bonang', 'PDF', '4.6 MB', 'Pompa Rob, Polder, Sayung, Pengendalian Banjir, SDA', 'Daftar spesifikasi teknis pompa air, jam operasional, debit sedot, dan kondisi genset cadangan untuk penanganan pasang air laut (rob) di pesisir Demak.'),
('BD-SDA-03', 'Data Panjang Tanggul Sungai dan Tanggul Laut Pengendali Banjir Kabupaten Demak', 'Data Spasial / GIS', 'sda', 2024, 'DINPUTARU-SDA/TANGGUL-2024', 'DINPUTARU Demak & BBWS Pemali Juana', '312,50 Km', 'Panjang Tanggul Pengendali Sungai & Laut', 'Sungai Wulan (86 Km), Sungai Tuntang (94 Km), Sungai Jragung (48 Km), Tanggul Penahan Rob Pesisir Sayung (84,5 Km)', 'SHP & PDF', '6.9 MB', 'Tanggul Banjir, Sungai Wulan, Sungai Tuntang, Mitigasi Bencana', 'Pemetaan kondisi elevasi tanggul kritis, titik rawan rembesan (seepage), dan tanggul sabuk pantai pesisir Sayung.'),
('BD-SDA-04', 'Data Luas Kawasan Rawan Genangan Banjir & Penurunan Rob yang Tertangani', 'Statistik BPS 2025', 'sda', 2024, 'DDA-2025/BPS-SDA/ROB-04', 'BPS Kab. Demak & BPBD / DINPUTARU Demak', '68,50%', 'Tingkat Penanganan Genangan Rob/Banjir', 'Dari 4.820 Ha kawasan rawan genangan teridentifikasi di 23 desa pesisir, 3.301 Ha telah terproteksi polder dan tanggul kolam retensi.', 'XLSX', '2.1 MB', 'Rob, Banjir, Pesisir Sayung, Penanganan Bencana, Capaian Kinerja', 'Hasil pengukuran luas genangan pasca pembangunan kolam retensi, tanggul sabuk laut, dan normalisasi saluran pembuang di pesisir utara Demak.'),
('BD-CK-01', 'Data Persentase Rumah Tangga dengan Akses Air Minum Layak Menurut Kecamatan', 'Statistik BPS 2025', 'cipta_karya', 2024, 'BPS-3321/DDA-2025/CK-01', 'BPS Kab. Demak (Demak Dalam Angka 2025, Tabel Sosial Budaya)', '93,42%', 'Akses Air Minum Layak Kabupaten Demak', 'Total Rumah Tangga: 372.450 KK | Air Minum Aman: 42,15% | PUDAM Tirtawijaya: 58.740 Sambungan Rumah | SPAM Perdesaan Aktif: 182 Desa', 'XLSX & PDF', '2.9 MB', 'BPS 2025, Air Minum Layak, PUDAM, SPAM, Cipta Karya', 'Cakupan akses air minum aman dan layak di seluruh kecamatan di Kabupaten Demak bersumber dari hasil Susenas BPS Kabupaten Demak.'),
('BD-CK-02', 'Data Akses Sanitasi Layak dan Verifikasi Desa Bebas Buang Air Besar Sembarangan (ODF)', 'Statistik BPS 2025', 'cipta_karya', 2024, 'BPS-3321/DDA-2025/CK-02', 'BPS Kab. Demak (Demak Dalam Angka 2025) & Seksi Sanitasi DINPUTARU', '88,64%', 'Rumah Tangga Bersanitasi Layak', '100% Desa/Kelurahan se-Kabupaten Demak telah lolos verifikasi ODF (Open Defecation Free) dengan kepemilikan jamban dan tangki septik standar SNI.', 'PDF & XLSX', '3.7 MB', 'BPS 2025, Sanitasi, Jamban Sehat, ODF, Tangki Septik', 'Data perkembangan penyediaan sarana pengolahan air limbah domestik skala individual (SPALD-S) dan komunal (SPALD-T) di permukiman padat.'),
('BD-CK-03', 'Data Panjang Saluran Drainase Perkotaan dan Kinerja Pematusan Genangan Hujan', 'Laporan Teknis', 'cipta_karya', 2024, 'DINPUTARU-CK/DRAINASE-2024', 'Bidang Cipta Karya DINPUTARU Kabupaten Demak', '185,40 Km', 'Panjang Jaringan Drainase Perkotaan', 'Kondisi Berfungsi Baik: 145,50 Km (78,5%) | Normalisasi & Pemeliharaan Berkala: 39,90 Km di Kawasan Perkotaan Demak & Mranggen', 'PDF & SHP', '4.8 MB', 'Drainase Perkotaan, Genangan Hujan, Cipta Karya, Perkotaan Demak', 'Peta jaringan primer, sekunder, dan tersier drainase perkotaan Demak guna mengatasi limpasan air hujan pada kawasan pemukiman dan perdagangan.'),
('BD-CK-04', 'Data Penerbitan Persetujuan Bangunan Gedung (PBG) & Sertifikat Laik Fungsi (SLF)', 'Regulasi & Legalitas', 'cipta_karya', 2024, 'DINPUTARU-CK/SIMBG-PBG/2024', 'Sistem Informasi SIMBG DINPUTARU Kabupaten Demak', '1.150 Dokumen', 'PBG & SLF Diterbitkan Tahun 2024', 'PBG Bangunan Hunian: 890 Berkas | Bangunan Usaha & Pabrik: 185 Berkas | Gedung Pelayanan Sosial/Fasum: 75 Berkas', 'XLSX', '1.5 MB', 'PBG, SLF, SIMBG, Bangunan Gedung, Perizinan', 'Laporan akuntabilitas pelayanan teknis perizinan gedung bangunan sesuai standar keandalan keselamatan dan ketahanan gempa di Demak.'),
('BD-TR-01', 'Data Luas Wilayah dan Penggunaan Lahan Menurut Kecamatan di Kabupaten Demak', 'Statistik BPS 2025', 'tata_ruang', 2024, 'BPS-3321/DDA-2025/TR-01', 'BPS Kab. Demak (Demak Dalam Angka 2025, Bab Geografi)', '897,43 Km²', 'Total Luas Wilayah Kabupaten Demak', '89.743 Hektar | Sawah: 48.950 Ha (54,5%) | Permukiman: 22.180 Ha | Tambak/Perikanan: 8.420 Ha | Industri & Jasa: 4.150 Ha | Hutan & Mangrove: 2.110 Ha', 'XLSX & SHP', '7.5 MB', 'BPS 2025, Tata Ruang, Penggunaan Lahan, Geografi Demak, RTRW', 'Data luas wilayah administratif 14 kecamatan di Kabupaten Demak beserta matriks perubahan tutupan lahan hasil penginderaan jauh citra satelit.'),
('BD-TR-02', 'Data Penetapan Kawasan Pertanian Pangan Berkelanjutan (KP2B / LP2B) Perda RTRW', 'Regulasi & Kebijakan', 'tata_ruang', 2024, 'PERDA-DEMAK/RTRW-LP2B/2020', 'Perda Kab. Demak No. 1/2020 tentang Perubahan RTRW & Bidang Tata Ruang', '46.280 Ha', 'Luas Baku Lahan Sawah Abadi (LP2B)', 'Dilindungi dari alih fungsi lahan komersial guna menjamin ketahanan pangan nasional di sentra lumbung beras Gajah, Dempet, Karanganyar, dan Wonosalam.', 'PDF & SHP', '5.8 MB', 'LP2B, KP2B, Lahan Padi Abadi, Ketahanan Pangan, RTRW', 'Peta deliniasi poligon spasial lahan sawah yang dilindungi secara hukum dari konversi industri dan permukiman di Kabupaten Demak.'),
