-- ==============================================================================
-- DATABASE: SIDAT - SATUPUTARU (Sistem Informasi Capaian Kinerja & Satu Data)
-- DINAS PEKERJAAN UMUM DAN PENATAAN RUANG (DINPUTARU) KABUPATEN DEMAK
-- Ekspor Lengkap Siap Import untuk Hostinger MySQL (cPanel / hPanel / phpMyAdmin)
-- Versi: 3.0 (Tema Biru PUPR, 6 Kategori Excel, 55 Indikator, Bank Data BPS 2025)
-- ==============================================================================

SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+07:00";

-- ------------------------------------------------------------------------------
-- 1. TABEL: system_settings (Identitas Sistem, Teks, & Logo PUPR)
-- ------------------------------------------------------------------------------
DROP TABLE IF EXISTS system_settings;
CREATE TABLE system_settings (
  setting_key VARCHAR(100) PRIMARY KEY,
  setting_value LONGTEXT NOT NULL,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value);

-- ------------------------------------------------------------------------------
-- 2. TABEL: roles (7 Peran Resmi Aparatur)
-- ------------------------------------------------------------------------------
DROP TABLE IF EXISTS roles;
CREATE TABLE roles (
  id VARCHAR(50) PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  description TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------------------------
-- 3. TABEL: bidang (Struktur Organisasi DINPUTARU Demak)
-- ------------------------------------------------------------------------------
DROP TABLE IF EXISTS bidang;
CREATE TABLE bidang (
  id VARCHAR(50) PRIMARY KEY,
  code VARCHAR(20) NOT NULL UNIQUE,
  name VARCHAR(150) NOT NULL,
  head VARCHAR(150),
  seksi VARCHAR(200),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------------------------
-- 4. TABEL: users (Akun Pengguna Internal DINPUTARU)
-- ------------------------------------------------------------------------------
DROP TABLE IF EXISTS users;
CREATE TABLE users (
  id VARCHAR(50) PRIMARY KEY,
  username VARCHAR(100) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  name VARCHAR(150) NOT NULL,
  nip VARCHAR(50),
  email VARCHAR(150) NOT NULL UNIQUE,
  phone VARCHAR(30),
  role_id VARCHAR(50) NOT NULL,
  bidang_id VARCHAR(50) NOT NULL,
  status VARCHAR(20) DEFAULT 'active',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY fk_users_role (role_id),
  KEY fk_users_bidang (bidang_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------------------------
-- 5. TABEL: categories (6 Kategori Indikator Sesuai Sheet Excel)
-- ------------------------------------------------------------------------------
DROP TABLE IF EXISTS categories;
CREATE TABLE categories (
  id VARCHAR(50) PRIMARY KEY,
  code VARCHAR(50) NOT NULL UNIQUE,
  segment_number INT NOT NULL,
  name VARCHAR(150) NOT NULL,
  description TEXT,
  badge_color VARCHAR(30) DEFAULT '#0B3C84',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------------------------
-- 6. TABEL: indicators (55 Indikator Kinerja Resmi DINPUTARU Kab. Demak)
-- ------------------------------------------------------------------------------
DROP TABLE IF EXISTS indicators;
CREATE TABLE indicators (
  id VARCHAR(50) PRIMARY KEY,
  code VARCHAR(50) NOT NULL UNIQUE,
  name VARCHAR(255) NOT NULL,
  category_id VARCHAR(50) NOT NULL,
  bidang_id VARCHAR(50) NOT NULL,
  wewenang_bidang VARCHAR(150),
  pejabat_penanggung_jawab VARCHAR(150),
  seksi_pelaksana VARCHAR(200),
  unit VARCHAR(50) NOT NULL DEFAULT '%',
  polarization VARCHAR(20) NOT NULL DEFAULT 'maximize',
  definition TEXT,
  formula TEXT,
  source VARCHAR(255),
  sort_order INT DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY fk_ind_cat (category_id),
  KEY fk_ind_bidang (bidang_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------------------------
-- 7. TABEL: target_realisasi (Data Target & Realisasi Periode 2020 s.d. 2030)
-- ------------------------------------------------------------------------------
DROP TABLE IF EXISTS target_realisasi;
CREATE TABLE target_realisasi (
  id INT AUTO_INCREMENT PRIMARY KEY,
  indicator_id VARCHAR(50) NOT NULL,
  year INT NOT NULL,
  target DECIMAL(12, 3) NOT NULL DEFAULT 0.000,
  realisasi DECIMAL(12, 3) NOT NULL DEFAULT 0.000,
  capaian_persen DECIMAL(7, 2) GENERATED ALWAYS AS (
    CASE 
      WHEN target > 0 THEN ROUND((realisasi / target) * 100, 2)
      ELSE 0.00 
    END
  ) STORED,
  notes TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_ind_year (indicator_id, year),
  KEY idx_year (year)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------------------------
-- 8. TABEL: bank_data (Data Resmi BPS Kab. Demak 2025 & Arsip Kedinasan)
-- ------------------------------------------------------------------------------
DROP TABLE IF EXISTS bank_data;
CREATE TABLE bank_data (
  id VARCHAR(50) PRIMARY KEY,
  title VARCHAR(255) NOT NULL,
  category VARCHAR(100) NOT NULL,
  bidang_id VARCHAR(50) NOT NULL,
  year INT NOT NULL,
  document_number VARCHAR(100),
  source VARCHAR(255),
  metric_value VARCHAR(100),
  metric_label VARCHAR(150),
  stat_summary TEXT,
  file_type VARCHAR(50) DEFAULT 'PDF',
  file_size VARCHAR(50),
  tags TEXT,
  description LONGTEXT,
  download_url VARCHAR(255),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  KEY idx_bd_bidang (bidang_id),
  KEY idx_bd_year (year)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------------------------
-- 9. TABEL: variables (Master Variabel Perhitungan Indikator)
-- ------------------------------------------------------------------------------
DROP TABLE IF EXISTS variables;
CREATE TABLE variables (
  id VARCHAR(50) PRIMARY KEY,
  code VARCHAR(50) NOT NULL UNIQUE,
  name VARCHAR(255) NOT NULL,
  category VARCHAR(100),
  unit VARCHAR(50),
  values_json JSON,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;
-- ==============================================================================
-- AKHIR FILE EKSPOR HOSTINGER MYSQL (SIDAT - SATUPUTARU KAB. DEMAK)
-- ==============================================================================
